import fs from 'fs';
import path from 'path';
import os from 'os';
import { randomUUID } from 'crypto';
import { createLogger } from '../utils/logger';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';
import { PROXY_URL } from '../config/proxy';
import {
  getRequestAuthContext,
  updateRequestAuthContext,
} from './RequestAuthContext';
import { getJwtSub, getJwtDisplayName } from './accessTokenRefresh';
import { parseInstallRef } from '../utils/installRef';
import { getTelemetryMode } from '../config/telemetryPolicy';
import { BrowserAuthorizationRecords } from '../storage/library/BrowserAuthorizationRecords';
import {
  parseThemePreference,
  type ThemePreference,
} from '../types/theme-preference';

const log = createLogger('ConfigManager');
const MAX_TRACKED_INSTALL_REFS = 20;

export interface AccountIdentity {
  userId?: string;
  email?: string;
}

export type InstallRefActivationTrigger = 'first_run' | 'sign_in';

export type InstallRefActivation = {
  installRef: string;
  trigger: InstallRefActivationTrigger;
  downloadType?: string;
  userId?: string;
};

type InstallRefActivationRecord = {
  installRef: string;
  downloadType?: string;
  signInUserId?: string;
  pendingTriggers: InstallRefActivationTrigger[];
  reportedTriggers: InstallRefActivationTrigger[];
};

const queueInstallRefTrigger = ({
  records = [],
  installRef,
  trigger,
  downloadType,
  signInUserId,
}: {
  records?: InstallRefActivationRecord[];
  installRef: string;
  trigger: InstallRefActivationTrigger;
  downloadType?: string;
  signInUserId?: string;
}): InstallRefActivationRecord[] => {
  const existing = records.find((record) => record.installRef === installRef);
  const record: InstallRefActivationRecord = existing ?? {
    installRef,
    pendingTriggers: [],
    reportedTriggers: [],
  };
  const isKnownTrigger =
    record.pendingTriggers.includes(trigger) ||
    record.reportedTriggers.includes(trigger);
  const updated: InstallRefActivationRecord = isKnownTrigger
    ? record
    : {
        ...record,
        downloadType: record.downloadType ?? downloadType,
        ...(signInUserId ? { signInUserId } : {}),
        pendingTriggers: [...record.pendingTriggers, trigger],
      };
  const others = records.filter((entry) => entry.installRef !== installRef);
  return [...others, updated].slice(-MAX_TRACKED_INSTALL_REFS);
};

const hasPendingInstallRefTriggers = (
  records: InstallRefActivationRecord[] = [],
): boolean => records.some((record) => record.pendingTriggers.length > 0);

type RivetConfig = {
  authToken?: string;
  refreshToken?: string;
  email?: string;
  userId?: string;
  proxyUrl?: string;
  anonymousId?: string;
  pluginTelemetryId?: string;
  telemetryIdentifiedEmail?: string;
  telemetryIdentifiedUserId?: string;
  firstVariantsRunAt?: string;
  mcpRemovedTelemetryDay?: string;
  runner?: string;
  runnerPaths?: Partial<Record<'claude' | 'codex' | 'cursor', string>>;
  workerVendor?: string;
  workerVendorFallback?: boolean;
  workerModels?: Partial<Record<'claude' | 'codex' | 'cursor', string>>;
  installRef?: string;
  installRefActivations?: InstallRefActivationRecord[];
  themePreference?: ThemePreference;
};

interface ConfigManagerOptions {
  configPath?: string;
}

interface AuthCommitOptions {
  expectedGeneration?: string;
  isRecovery?: boolean;
}

const authFields = (config: RivetConfig) => ({
  authToken: config.authToken,
  refreshToken: config.refreshToken,
  email: config.email,
  userId: config.userId,
});

const storedIdentity = (config: RivetConfig): string | null => {
  if (!config.authToken) return null;
  return config.userId ?? getJwtSub(config.authToken) ?? config.email ?? null;
};

export class ConfigManager {
  private configPath: string;
  private config: RivetConfig;
  private authorization: BrowserAuthorizationRecords | undefined;

  constructor(options: ConfigManagerOptions = {}) {
    const homeDir = os.homedir();
    this.configPath =
      options.configPath ?? path.join(homeDir, '.rivet', 'config.json');
    const rivetDir = path.dirname(this.configPath);

    if (!fs.existsSync(rivetDir)) {
      fs.mkdirSync(rivetDir, { recursive: true, mode: 0o700 });
      log.debug(`Created Rivet config directory: ${rivetDir}`);
    }

    this.config = this.loadConfig();
  }

  private canUseStoredAuthForRequest(requestToken?: string): boolean {
    return !!requestToken && requestToken === this.config.authToken;
  }

  private loadConfig(fallback: RivetConfig = {}): RivetConfig {
    if (!fs.existsSync(this.configPath)) {
      return {};
    }
    try {
      const data = fs.readFileSync(this.configPath, 'utf8');
      const config = JSON.parse(data);
      return config;
    } catch (error) {
      log.warn('Failed to load config:', error);
    }
    return fallback;
  }

  private reloadConfigFromDisk(): void {
    this.config = this.loadConfig(this.config);
  }

  private saveConfig(): void {
    this.getBrowserAuthorization().saveSettings(() => {
      const current = this.loadStoredConfig();
      this.config = { ...this.config, ...authFields(current) };
      this.writeConfig();
    });
  }

  private writeConfig(): void {
    try {
      writeFileAtomicSync(
        this.configPath,
        JSON.stringify(this.config, null, 2),
        { mode: 0o600 },
      );
      log.debug(`Saved config to ${this.configPath}`);
    } catch (error) {
      log.error('Failed to save config:', error);
      throw new Error('Failed to save configuration');
    }
  }

  private loadStoredConfig(): RivetConfig {
    if (!fs.existsSync(this.configPath)) return {};
    const value: unknown = JSON.parse(fs.readFileSync(this.configPath, 'utf8'));
    if (!value || typeof value !== 'object' || Array.isArray(value))
      throw new Error('Stored Rivet configuration is invalid');
    return value as RivetConfig;
  }

  getStoredIdentity(): string | null {
    return storedIdentity(this.loadStoredConfig());
  }

  getBrowserAuthorization(): BrowserAuthorizationRecords {
    this.authorization ??= new BrowserAuthorizationRecords(
      path.join(path.dirname(this.configPath), 'browser-authorization.sqlite'),
    );
    return this.authorization;
  }

  getAuthorizationGeneration(): string {
    return this.getBrowserAuthorization().snapshot(() =>
      this.getStoredIdentity(),
    ).generation;
  }

  beginSignIn(): string {
    return this.getBrowserAuthorization().signInGeneration(() =>
      this.getStoredIdentity(),
    );
  }

  close(): void {
    this.authorization?.close();
    this.authorization = undefined;
  }

  setAuth(
    token: string,
    email: string,
    refreshToken?: string,
    userId?: string,
    options: AuthCommitOptions = {},
  ): string {
    let target: RivetConfig = {};
    const snapshot = this.getBrowserAuthorization().mutateAccount({
      expectedGeneration: options.expectedGeneration,
      isRecovery: options.isRecovery,
      isIdentityEnrichment: () =>
        this.config.email === email &&
        storedIdentity(this.config) === email &&
        Boolean(target.userId),
      read: () => {
        this.config = this.loadStoredConfig();
        return storedIdentity(this.config);
      },
      next: () => {
        target = {
          authToken: token,
          refreshToken,
          email,
          userId:
            userId ??
            getJwtSub(token) ??
            (this.config.email === email ? this.config.userId : undefined),
        };
        return storedIdentity(target);
      },
      write: () => {
        this.config = { ...this.loadStoredConfig(), ...target };
        this.writeConfig();
      },
    });
    updateRequestAuthContext({
      token,
      refreshToken,
      email,
      userId: this.config.userId,
    });
    log.debug(`Saved auth tokens for ${email}`);
    return snapshot.generation;
  }

  getAuthToken(): string | undefined {
    this.reloadConfigFromDisk();
    const requestContext = getRequestAuthContext();
    if (requestContext) {
      return requestContext.token;
    }
    return this.config.authToken;
  }

  getRefreshToken(): string | undefined {
    this.reloadConfigFromDisk();
    const requestContext = getRequestAuthContext();
    if (requestContext) {
      return (
        requestContext.refreshToken ??
        (this.canUseStoredAuthForRequest(requestContext.token)
          ? this.config.refreshToken
          : undefined)
      );
    }
    return this.config.refreshToken;
  }

  getAccountIdentity(): AccountIdentity {
    this.reloadConfigFromDisk();
    const requestContext = getRequestAuthContext();
    if (requestContext) {
      const canUseStoredAuth = this.canUseStoredAuthForRequest(
        requestContext.token,
      );
      return {
        userId:
          requestContext.userId ??
          (canUseStoredAuth ? this.config.userId : undefined),
        email:
          requestContext.email ??
          (canUseStoredAuth ? this.config.email : undefined),
      };
    }
    const tokenUserId = this.config.authToken
      ? (getJwtSub(this.config.authToken) ?? undefined)
      : undefined;
    return {
      userId: this.config.userId || tokenUserId,
      email: this.config.email,
    };
  }

  getEmail(): string | undefined {
    return this.getAccountIdentity().email;
  }

  getUserId(): string | undefined {
    return this.getAccountIdentity().userId;
  }

  getDisplayName(): string | undefined {
    const token = this.getAuthToken();
    if (!token) {
      return undefined;
    }
    return getJwtDisplayName(token) ?? undefined;
  }

  isAuthenticated(): boolean {
    return !!this.getAuthToken();
  }

  clearAuth(): void {
    this.getBrowserAuthorization().mutateAccount({
      isLogout: true,
      read: () => this.getStoredIdentity(),
      next: () => null,
      write: () => {
        this.config = {
          ...this.loadStoredConfig(),
          ...authFields({}),
          telemetryIdentifiedEmail: undefined,
          telemetryIdentifiedUserId: undefined,
        };
        this.writeConfig();
      },
    });
    log.debug('Cleared authentication');
  }

  setProxyUrl(url: string): void {
    this.reloadConfigFromDisk();
    this.config.proxyUrl = url;
    this.saveConfig();
    log.debug(`Set proxy URL: ${url}`);
  }

  getPluginTelemetryId(): string {
    this.getBrowserAuthorization().saveSettings(() => {
      this.config = this.loadStoredConfig();
      if (
        !this.config.pluginTelemetryId?.match(
          /^plugin-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/,
        )
      ) {
        this.config.pluginTelemetryId = `plugin-${randomUUID()}`;
        this.writeConfig();
      }
    });
    if (!this.config.pluginTelemetryId)
      throw new Error('Plugin telemetry identity is unavailable');
    return this.config.pluginTelemetryId;
  }

  getAnonymousId(): string {
    if (!this.config.anonymousId) {
      this.config.anonymousId = `anon-${randomUUID()}`;
      this.saveConfig();
      log.debug(`Generated anonymous ID: ${this.config.anonymousId}`);
    }
    return this.config.anonymousId;
  }

  getTelemetryIdentifiedEmail(): string | undefined {
    return this.config.telemetryIdentifiedEmail;
  }

  setTelemetryIdentifiedEmail(email: string): void {
    this.config.telemetryIdentifiedEmail = email;
    this.saveConfig();
  }

  getTelemetryIdentifiedUserId(): string | undefined {
    return this.config.telemetryIdentifiedUserId;
  }

  setTelemetryIdentifiedUserId(userId: string): void {
    this.config.telemetryIdentifiedUserId = userId;
    this.saveConfig();
  }

  claimMcpRemovedTelemetryWindow(now: Date = new Date()): boolean {
    const day = now.toISOString().slice(0, 10);
    this.reloadConfigFromDisk();
    if (this.config.mcpRemovedTelemetryDay === day) return false;
    this.config.mcpRemovedTelemetryDay = day;
    this.saveConfig();
    return true;
  }

  getInstallRef(): string | undefined {
    this.reloadConfigFromDisk();
    return parseInstallRef(this.config.installRef);
  }

  setInstallRef(installRef: string, downloadType?: string): void {
    this.getBrowserAuthorization().saveSettings(() => {
      this.reloadConfigFromDisk();
      this.config.installRef = installRef;
      if (getTelemetryMode() !== 'off') {
        this.config.installRefActivations = queueInstallRefTrigger({
          records: this.config.installRefActivations,
          installRef,
          trigger: 'first_run',
          downloadType,
        });
      }
      this.writeConfig();
    });
  }

  clearInstallRef(installRef: string): void {
    this.reloadConfigFromDisk();
    if (this.config.installRef !== installRef) return;
    this.config.installRef = undefined;
    this.saveConfig();
  }

  completeInstallRefSignIn(
    installRef: string,
    userId: string | undefined,
  ): void {
    this.getBrowserAuthorization().saveSettings(() => {
      this.reloadConfigFromDisk();
      if (this.config.installRef === installRef) {
        this.config.installRef = undefined;
      }
      if (getTelemetryMode() !== 'off') {
        this.config.installRefActivations = queueInstallRefTrigger({
          records: this.config.installRefActivations,
          installRef,
          trigger: 'sign_in',
          signInUserId: userId,
        });
      }
      this.writeConfig();
    });
  }

  claimInstallRefActivations(): InstallRefActivation[] {
    this.reloadConfigFromDisk();
    if (!hasPendingInstallRefTriggers(this.config.installRefActivations)) {
      return [];
    }
    const claimed: InstallRefActivation[] = [];
    this.getBrowserAuthorization().saveSettings(() => {
      this.reloadConfigFromDisk();
      const records = this.config.installRefActivations ?? [];
      for (const record of records) {
        for (const trigger of record.pendingTriggers) {
          claimed.push({
            installRef: record.installRef,
            trigger,
            ...(record.downloadType
              ? { downloadType: record.downloadType }
              : {}),
            ...(trigger === 'sign_in' && record.signInUserId
              ? { userId: record.signInUserId }
              : {}),
          });
        }
      }
      if (claimed.length === 0) return;
      this.config.installRefActivations = records.map((record) => ({
        ...record,
        pendingTriggers: [],
        reportedTriggers: [
          ...record.reportedTriggers,
          ...record.pendingTriggers,
        ],
      }));
      this.writeConfig();
    });
    return claimed;
  }

  getThemePreference(): ThemePreference | null {
    this.reloadConfigFromDisk();
    return parseThemePreference(this.config.themePreference);
  }

  setThemePreference(preference: ThemePreference): void {
    this.getBrowserAuthorization().saveSettings(() => {
      this.reloadConfigFromDisk();
      this.config.themePreference = preference;
      this.writeConfig();
    });
  }

  getProxyUrl(): string {
    this.reloadConfigFromDisk();
    return this.config.proxyUrl || PROXY_URL;
  }

  getConfiguredRunner(): string | undefined {
    this.reloadConfigFromDisk();
    return this.config.runner;
  }

  getConfiguredRunnerPaths(): Record<string, unknown> | undefined {
    this.reloadConfigFromDisk();
    return this.config.runnerPaths;
  }

  getConfiguredWorkerVendor(): string | undefined {
    this.reloadConfigFromDisk();
    return this.config.workerVendor;
  }

  isWorkerVendorFallbackEnabled(): boolean {
    this.reloadConfigFromDisk();
    return this.config.workerVendorFallback === true;
  }

  getConfiguredWorkerModel(
    vendor: 'claude' | 'codex' | 'cursor',
  ): string | undefined {
    this.reloadConfigFromDisk();
    return this.config.workerModels?.[vendor];
  }

  getConfig(): RivetConfig {
    this.reloadConfigFromDisk();
    return { ...this.config };
  }

  getConfigPath(): string {
    return this.configPath;
  }
}

let configManager: ConfigManager | null = null;

export const getConfigManager = (): ConfigManager => {
  if (!configManager) {
    configManager = new ConfigManager();
  }
  return configManager;
};
